(()=>{'use strict';
const E=window.MBBSRecallEngine, $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const MAIN=[['home','▦','Dashboard'],['study','◉','Study'],['cards','▤','All IMPs'],['workbook','▦','Workbook'],['analytics','▥','Analytics'],['settings','⚙','Settings']];
const WBTABS=[['dashboard','Dashboard'],['today','TODAY DUE'],['week','THIS WEEK'],['master','Master Entry'],['revision','Revision Log'],['weak','Weak Topics'],['unit','Unit Progress'],['subjects','Subject Sheets'],['units','Unit Management'],['intervals','Intervals']];
const fresh=()=>JSON.parse(JSON.stringify(window.MBBS_WORKBOOK_SEED));
let state=null, computed=null, mainTab='home', wbTab='dashboard', subjectSheet='Medicine', search='', subjectFilter='All', statusFilter='All', sortCards='id-asc', selectedIds=new Set(), page=0, pageSize=50, revPage=0, revSearch='', modal=null, study={queue:[],idx:0,revealed:false,includeNew:true,weak:false,shuffle:false}, undoSnapshot=null, saveChain=Promise.resolve(), saveTimer=null, db=null, isLoading=true, saveStateLabel='Starting…', toasts=[], tests=[];
function clone(x){return JSON.parse(JSON.stringify(x))}
function normalizeState(x){const seed=fresh();return {version:5,master:Array.isArray(x?.master)?x.master.filter(v=>v&&typeof v==='object'&&!Array.isArray(v)).map(v=>({...v})):seed.master,revisions:Array.isArray(x?.revisions)?x.revisions.filter(v=>v&&typeof v==='object'&&!Array.isArray(v)).map(v=>({...v})):seed.revisions,examDate:typeof x?.examDate==='string'?x.examDate:'',intervals:x?.intervals&&typeof x.intervals==='object'?x.intervals:seed.intervals,units:x?.units&&typeof x.units==='object'?x.units:seed.units,meta:{...(x?.meta||{}),updatedAt:new Date().toISOString()}}}
function openDB(){return new Promise((resolve,reject)=>{if(!('indexedDB'in window))return reject(Error('IndexedDB unavailable'));const req=indexedDB.open('mbbs-recall-pro-v5',1);req.onupgradeneeded=()=>{const d=req.result;if(!d.objectStoreNames.contains('state'))d.createObjectStore('state',{keyPath:'key'})};req.onsuccess=()=>{db=req.result;resolve(db)};req.onerror=()=>reject(req.error||Error('DB open failed'))})}
function dbGet(){return new Promise((resolve,reject)=>{const tx=db.transaction('state','readonly'),r=tx.objectStore('state').get('main');r.onsuccess=()=>resolve(r.result?.value||null);r.onerror=()=>reject(r.error)})}
function dbPut(v){return new Promise((resolve,reject)=>{const tx=db.transaction('state','readwrite');tx.objectStore('state').put({key:'main',value:v,savedAt:Date.now()});tx.oncomplete=()=>resolve(true);tx.onerror=()=>reject(tx.error||Error('Save transaction failed'));tx.onabort=()=>reject(tx.error||Error('Save transaction aborted'))})}
async function boot(){try{await openDB();const saved=await dbGet();state=normalizeState(saved||fresh());if(!saved)await dbPut(state);saveStateLabel='Saved on this device'}catch(err){try{const raw=localStorage.getItem('mbbs-recall-pro-v5');state=normalizeState(raw?JSON.parse(raw):fresh());saveStateLabel='Local fallback storage';}catch(e){state=normalizeState(fresh());saveStateLabel='Storage unavailable — export backups';toast('Local storage is unavailable. Export a backup regularly.','error')}}isLoading=false;recalc();render();if('serviceWorker'in navigator&&/^https?:$/.test(location.protocol))navigator.serviceWorker.register('./sw.js').catch(()=>{});$('#headStatus').textContent='Workbook-aligned • offline-first • '+state.master.length+' IMPs';}
function recalc(){computed=E.compute(state,E.today())}
function save(){if(!state)return;state.meta={...(state.meta||{}),updatedAt:new Date().toISOString()};saveStateLabel='Saving…';updateSaveLabel();const snap=clone(state);saveChain=saveChain.then(async()=>{try{if(db)await dbPut(snap);else throw Error('IndexedDB unavailable');saveStateLabel='Saved locally · '+new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'});}catch(err){try{localStorage.setItem('mbbs-recall-pro-v5',JSON.stringify(snap));saveStateLabel='Saved in browser storage';}catch(e){saveStateLabel='SAVE FAILED — export backup';toast('Could not save data. Export a backup immediately.','error')}}updateSaveLabel()});}
function commit(next,msg){state=normalizeState(next);recalc();render();save();if(msg)toast(msg)}
function updateSaveLabel(){const el=$('#saveStatus');if(el)el.textContent=saveStateLabel}
function toast(msg,type='ok',action){const area=$('#toasts');if(!area)return;const d=document.createElement('div');d.className='toast';d.innerHTML=`${esc(msg)}${action?` <button data-action="${action}">Undo</button>`:''}`;area.append(d);setTimeout(()=>{d.remove()},5000)}
function setMain(tab){mainTab=tab;if(tab==='study'&&!study.queue.length)buildQueue();render()}
function button(label,action,cls='btn',attrs=''){return `<button class="${cls}" data-action="${action}" ${attrs}>${label}</button>`}
function metric(label,value,hint='',color=''){return `<div class="metric"><div class="label">${esc(label)}</div><div class="value" ${color?`style="color:${color}"`:''}>${esc(value)}</div><div class="hint">${esc(hint)}</div></div>`}
function pageTitle(title,desc,actions=''){return `<div class="page-title"><div><h1>${esc(title)}</h1><div class="muted smalltext">${esc(desc||'')}</div></div><div class="actions">${actions}</div></div>`}
function pillResult(r){let cls=r==='PASS'?'pass':r==='FAIL'?'fail':r==='PARTIAL'?'partial':'';return `<span class="pill ${cls}">${esc(r||'—')}</span>`}
function statusPill(c){if(c.dataQuality)return `<span class="pill issue">Data issue</span>`;if(c.nextDue&&c.nextDue<=E.today())return `<span class="pill due">${esc(c.status)}</span>`;if(!c.nextDue)return `<span class="pill done">Done</span>`;return `<span class="pill">${esc(c.status)}</span>`}
function render(){if(!state)return;$('#topnav').innerHTML=MAIN.map(([id,ico,label])=>`<button class="navbtn ${mainTab===id?'active':''}" data-tab="${id}">${ico} &nbsp;${label}</button>`).join('');$('#mobilebar').innerHTML=MAIN.filter(x=>['home','study','cards','workbook','settings'].includes(x[0])).map(([id,ico,label])=>`<button class="${mainTab===id?'active':''}" data-tab="${id}"><span class="ico">${ico}</span>${label}</button>`).join('');$('#headStatus').textContent=`Workbook-aligned • offline-first • ${state.master.length} IMPs • ${computed.dashboard.dueToday} due`;updateSaveLabel();const v=$('#view');if(mainTab==='home')v.innerHTML=renderDashboard();else if(mainTab==='study')v.innerHTML=renderStudy();else if(mainTab==='cards')v.innerHTML=renderCards();else if(mainTab==='workbook')v.innerHTML=renderWorkbook();else if(mainTab==='analytics')v.innerHTML=renderAnalytics();else v.innerHTML=renderSettings();if(modal)renderModal()}
function renderDashboard(){const d=computed.dashboard, cards=computed.due.slice().sort((a,b)=>a.nextDue.localeCompare(b.nextDue)).slice(0,8);return `${pageTitle('Your study cockpit','Live overview of your workbook-based spaced repetition.',button('＋ Add IMP','add-card','btn primary')+button('Start due review','start-study','btn teal'))}<div class="grid metrics">${metric('Total IMPs',d.totalIMPs,'Stored study questions')}${metric('Due today',d.dueToday,'Includes overdue',d.dueToday?'#a16207':'')}${metric('Due in 7 days',d.dueNext7,'Overdue included')}${metric('Mastered',d.mastered,'Stage 4–5')}</div><div class="grid split" style="margin-top:12px"><section class="panel"><h2>Due next</h2>${cards.length?`<div class="tablewrap"><table><thead><tr><th>ID</th><th>Question</th><th>Subject / Unit</th><th>Due</th><th></th></tr></thead><tbody>${cards.map(c=>`<tr><td>#${c.id}</td><td class="wrap">${esc(c.question)}</td><td>${esc(c.subject)}<div class="muted tiny">${esc(c.unit)}</div></td><td>${esc(c.nextDue)}</td><td>${button('Study','study-card','btn small',`data-id="${c.id}"`)}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">Nothing is due today. Use the week view to plan ahead.</div>`}${button('Open TODAY DUE →','wb-today','btn')}</section><section class="panel"><h2>Progress by subject</h2>${computed.subjects.filter(s=>s.total||s.dueToday).sort((a,b)=>b.total-a.total).slice(0,8).map(s=>`<div class="barline"><span>${esc(s.subject)}</span><div class="bar"><i style="width:${s.progress}%"></i></div><b>${s.progress}%</b></div>`).join('')||'<div class="empty">Add IMPs to see progress.</div>'}<div class="notice">Stage 4–5 is counted as mastered, matching the workbook’s Unit Progress logic.</div></section></div><div class="grid metrics" style="margin-top:12px">${metric('Never revised',d.neverRevised,'New cards')}${metric('In progress',d.inProgress,'Stage 2–3')}${metric('Pass rate',`${Math.round(d.overallPassRate*100)}%`,'Across valid recorded results')}${metric('Data issues',d.dataIssues+d.revisionIssues,'Review in Workbook → Diagnostics',d.dataIssues+d.revisionIssues?'#b42318':'')}</div>${d.capacityMasterWarn||d.capacityRevWarn?`<div class="notice warn">Capacity warning: workbook-style limits are 1,000 IMPs and 9,999 revision rows. Export a backup before approaching the limit.</div>`:''}`}
function renderStudy(){const c=computed.cards.find(x=>x.id===study.queue[study.idx]);const count=study.queue.length;return `${pageTitle('Study session','Reveal the answer, grade honestly, and let the schedule update automatically.',button('Rebuild queue','rebuild-queue','btn'))}<div class="panel studycard"><div class="toolbar"><label class="checkrow"><input type="checkbox" data-setting="includeNew" ${study.includeNew?'checked':''}> Include new</label><label class="checkrow"><input type="checkbox" data-setting="weak" ${study.weak?'checked':''}> Prioritize weak</label><label class="checkrow"><input type="checkbox" data-setting="shuffle" ${study.shuffle?'checked':''}> Shuffle</label><span class="muted tiny" style="margin-left:auto">${count?`Card ${study.idx+1} / ${count}`:'Queue empty'}</span></div>${c?`<div class="statusrow"><span class="pill">ID ${c.id}</span><span class="pill">${esc(c.subject)}</span><span class="pill">${esc(c.unit)}</span><span class="pill">${esc(c.priorityNormLabel||c.priority)}</span><span class="pill">Stage ${c.stage} · Streak ${c.streak}</span></div><div class="question">${esc(c.question)}</div><div class="muted smalltext">${c.source?`Source: ${esc(c.source)} · `:''}Next due: ${esc(c.nextDue||'Done')} · Attempts: ${c.totalAttempts}</div>${study.revealed?`<div class="answer" style="margin-top:14px">${esc(c.answer||'No answer key has been added yet.')}${c.notes?`\n\nNotes: ${esc(c.notes)}`:''}</div><div class="grade-row" style="margin-top:14px"><button class="grade fail" data-action="grade" data-result="FAIL">✕ FAIL <span class="tiny">· 1 key</span></button><button class="grade partial" data-action="grade" data-result="PARTIAL">◐ PARTIAL <span class="tiny">· 2 days</span></button><button class="grade pass" data-action="grade" data-result="PASS">✓ PASS <span class="tiny">· stage interval</span></button></div>`:button('Reveal answer · Space','reveal','btn primary',`style="margin-top:15px;width:100%;padding:13px"`)}<div class="toolbar" style="margin-top:12px;margin-bottom:0">${button('← Previous','study-prev','btn')}${button('Skip →','study-next','btn')}<span class="muted tiny" style="margin-left:auto">Keys: <span class="kbd">Space</span> reveal · <span class="kbd">1</span> fail · <span class="kbd">2</span> partial · <span class="kbd">3</span> pass</span></div>`:`<div class="empty"><h3>No cards in this queue</h3><p>Either all valid cards are done or all due cards are blocked by data-quality issues.</p>${button('Build queue','rebuild-queue','btn primary')} ${button('Review data issues','wb-master','btn')}</div>`}</div><div class="footnote">A grade appends a revision row. Use Undo if you grade a card by mistake. Do not clear browser storage before exporting a backup.</div>`}
function filteredCards(){let a=computed.cards.slice();if(search){const q=search.toLowerCase();a=a.filter(c=>[c.question,c.answer,c.subject,c.unit,c.source,c.notes,String(c.id)].some(v=>String(v||'').toLowerCase().includes(q)))}if(subjectFilter!=='All')a=a.filter(c=>c.subject===subjectFilter);if(statusFilter==='Due')a=a.filter(c=>c.nextDue&&c.nextDue<=E.today()&&!c.dataQuality);if(statusFilter==='New')a=a.filter(c=>c.new);if(statusFilter==='Weak')a=a.filter(c=>c.fails>0);if(statusFilter==='Done')a=a.filter(c=>!c.nextDue&&!c.dataQuality);if(statusFilter==='Data Issues')a=a.filter(c=>!!c.dataQuality);const cmp=(x,y)=>String(x??'').localeCompare(String(y??''),undefined,{numeric:true,sensitivity:'base'});const pri=c=>({'Late':0,'Must-Do':1,'Regular':2}[c.priorityNormLabel||c.priority]??9);const sorters={'id-asc':(x,y)=>x.id-y.id,'id-desc':(x,y)=>y.id-x.id,'subject':(x,y)=>cmp(x.subject,y.subject)||cmp(x.unit,y.unit)||x.id-y.id,'due':(x,y)=>cmp(x.nextDue||'9999-99-99',y.nextDue||'9999-99-99')||x.id-y.id,'priority':(x,y)=>pri(x)-pri(y)||x.id-y.id,'weak':(x,y)=>y.fails-x.fails||y.failRate-x.failRate||x.id-y.id};return a.sort(sorters[sortCards]||sorters['id-asc'])}
function cardTable(cards,selectable=false){return `<div class="tablewrap"><table><thead><tr>${selectable?`<th><input type="checkbox" aria-label="Select visible IMPs" data-select-visible="true" ${cards.length&&cards.every(c=>selectedIds.has(Number(c.id)))?'checked':''}></th>`:''}<th>ID</th><th>Question / IMP</th><th>Subject</th><th>Unit</th><th>Priority</th><th>Attempts</th><th>Pass / Fail</th><th>Stage</th><th>Last Result</th><th>Next Due</th><th>Status</th><th>Actions</th></tr></thead><tbody>${cards.map(c=>`<tr>${selectable?`<td><input type="checkbox" aria-label="Select IMP ${c.id}" data-select-id="${c.id}" ${selectedIds.has(Number(c.id))?'checked':''}></td>`:''}<td><b>#${c.id}</b></td><td class="wrap"><b>${esc(c.question)}</b>${c.answer?`<div class="muted tiny" style="margin-top:4px">${esc(c.answer.slice(0,100))}${c.answer.length>100?'…':''}</div>`:''}${c.dataQuality?`<div class="tiny" style="color:#a12620;margin-top:4px">${esc(c.dataQuality)}</div>`:''}</td><td>${esc(c.subject)}</td><td>${esc(c.unit)}</td><td>${esc(c.priorityNormLabel||c.priority||'—')}</td><td>${c.totalAttempts}</td><td>${c.passes} / ${c.fails}</td><td>${c.stage}</td><td>${pillResult(c.lastResult)}</td><td>${esc(c.nextDue||'—')}</td><td>${statusPill(c)}</td><td><div class="actions">${button('Study','study-card','btn small',`data-id="${c.id}"`)}${button('Edit','edit-card','btn small',`data-id="${c.id}"`)}${button('Delete','delete-card','btn small danger',`data-id="${c.id}"`)}</div></td></tr>`).join('')||`<tr><td colspan="${selectable?13:12}" class="empty">No matching IMPs found.</td></tr>`}</tbody></table></div>`}
function renderCards(){const all=filteredCards(),start=page*pageSize,shown=all.slice(start,start+pageSize);return `${pageTitle('All IMPs','Search, filter, sort, bulk-select, edit, delete and review every saved question.',button('Import XLSX / CSV','import-file','btn')+button('Export full CSV','export-cards','btn')+button('＋ New IMP','add-card','btn primary'))}<div class="panel"><div class="toolbar"><input class="field" id="searchBox" data-filter="search" value="${esc(search)}" placeholder="Search ID, question, answer, subject, unit…"><select class="select" data-filter="subject"><option>All</option>${E.SUBJECTS.map(s=>`<option ${subjectFilter===s?'selected':''}>${esc(s)}</option>`).join('')}</select><select class="select" data-filter="status"><option ${statusFilter==='All'?'selected':''}>All</option>${['Due','New','Weak','Done','Data Issues'].map(s=>`<option ${statusFilter===s?'selected':''}>${s}</option>`).join('')}</select><select class="select" data-filter="sort" aria-label="Sort IMPs">${[['id-asc','ID ↑'],['id-desc','ID ↓'],['subject','Subject / Unit'],['due','Next due date'],['priority','Priority'],['weak','Most failures']].map(([v,l])=>`<option value="${v}" ${sortCards===v?'selected':''}>Sort: ${l}</option>`).join('')}</select><button class="btn" data-action="clear-filters">Clear filters</button></div><div class="toolbar"><button class="btn" data-action="select-matching">Select all ${all.length} matching</button><button class="btn" data-action="clear-selection">Clear selection</button><button class="btn danger" data-action="delete-selected" ${selectedIds.size?'':'disabled'}>Delete selected (${selectedIds.size})</button><span class="muted tiny">Selection can span pages; deleting also removes linked reviews and can be undone.</span></div><div class="statusrow" style="margin-bottom:10px"><span class="pill">${all.length} matching</span><span class="muted tiny">Showing ${all.length?start+1:0}–${Math.min(start+pageSize,all.length)} of ${all.length} · Page size ${pageSize}</span></div>${cardTable(shown,true)}<div class="pagination"><span class="muted tiny">All records are stored locally; table is paginated for phone performance.</span><div class="actions">${button('← Previous','cards-prev','btn small',page===0?'disabled':'')}${button('Next →','cards-next','btn small',start+pageSize>=all.length?'disabled':'')}</div></div></div>`}
function renderWorkbook(){let body='';if(wbTab==='dashboard')body=renderWorkbookDashboard();if(wbTab==='today')body=renderDueTable(false);if(wbTab==='week')body=renderDueTable(true);if(wbTab==='master')body=renderMasterTable();if(wbTab==='revision')body=renderRevisionTable();if(wbTab==='weak')body=renderWeak();if(wbTab==='unit')body=renderUnitProgress();if(wbTab==='subjects')body=renderSubjects();if(wbTab==='units')body=renderUnits();if(wbTab==='intervals')body=renderIntervals();return `${pageTitle('Workbook views','Navigate the same core sections as the Google Sheets workbook.',button('＋ New IMP','add-card','btn primary'))}<div class="subnav">${WBTABS.map(([id,label])=>`<button data-wbtab="${id}" class="${wbTab===id?'active':''}">${label}</button>`).join('')}</div>${body}`}
function renderWorkbookDashboard(){const d=computed.dashboard;return `<div class="grid metrics">${metric('Total IMPs',d.totalIMPs,'Master Entry')}${metric('Due today',d.dueToday,'TODAY DUE')}${metric('Due + 7 days',d.dueNext7,'THIS WEEK')}${metric('Revisions logged',d.totalRevs,'Revision Log')}</div><div class="grid split" style="margin-top:12px"><section class="panel"><h2>Workbook sections</h2><div class="subjectgrid">${WBTABS.filter(x=>x[0]!=='dashboard').map(([id,label])=>`<button class="subjectcard" data-wbtab="${id}"><strong>${esc(label)}</strong><div class="substats">Open view →</div></button>`).join('')}</div></section><section class="panel"><h2>Data quality & capacity</h2><div class="barline"><span>IMP capacity</span><div class="bar"><i style="width:${Math.min(100,d.totalIMPs/1000*100)}%"></i></div><b>${d.totalIMPs}/1000</b></div><div class="barline"><span>Revision capacity</span><div class="bar"><i style="width:${Math.min(100,state.revisions.length/9999*100)}%"></i></div><b>${state.revisions.length}/9999</b></div><div class="notice ${d.dataIssues+d.revisionIssues?'warn':'good'}">${d.dataIssues+d.revisionIssues?`${d.dataIssues} IMPs and ${d.revisionIssues} revision rows need attention.`:'No current data-quality issues detected.'}</div>${button('Run diagnostics','run-tests','btn')}</section></div>`}
function renderDueTable(week){const list=(week?computed.week:computed.due).slice().sort((a,b)=>a.nextDue.localeCompare(b.nextDue));return `${pageTitle(week?'THIS WEEK':'TODAY DUE',week?'All valid cards due within the next 7 days, including overdue.':'Valid cards due today or overdue, sorted by next due date.',button('Study this queue','study-due','btn primary')+button('Export CSV','export-cards','btn'))}<div class="panel"><div class="statusrow" style="margin-bottom:10px"><span class="pill ${list.length?'due':'done'}">${list.length} cards</span><span class="muted tiny">Data-quality flagged cards are excluded, as in the workbook.</span></div>${cardTable(list,true)}</div>`}
function renderMasterTable(){const all=filteredCards(),start=page*pageSize,shown=all.slice(start,start+pageSize);return `${pageTitle('Master Entry','Full workbook-style view: source fields, review calculations, status, and data-quality flags.',button('Import .xlsx workbook','import-file','btn')+button('＋ Add IMP','add-card','btn primary')+button('Export CSV','export-cards','btn'))}<div class="panel"><div class="toolbar"><input class="field" data-filter="search" value="${esc(search)}" placeholder="Search ID, question, answer, subject, unit…"><select class="select" data-filter="subject"><option>All</option>${E.SUBJECTS.map(s=>`<option ${subjectFilter===s?'selected':''}>${esc(s)}</option>`).join('')}</select><select class="select" data-filter="status"><option value="All" ${statusFilter==='All'?'selected':''}>All statuses</option>${['Due','New','Weak','Done','Data Issues'].map(s=>`<option ${statusFilter===s?'selected':''}>${s}</option>`).join('')}</select><select class="select" data-filter="sort">${[['id-asc','ID ↑'],['id-desc','ID ↓'],['subject','Subject / Unit'],['due','Next due'],['priority','Priority'],['weak','Most failures']].map(([v,l])=>`<option value="${v}" ${sortCards===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="statusrow" style="margin-bottom:9px"><span class="pill">${all.length} records</span><span class="muted tiny">Showing ${all.length?start+1:0}–${Math.min(start+pageSize,all.length)} · scroll horizontally for workbook helper columns</span></div><div class="tablewrap"><table><thead><tr>${['ID','Entry Date','Subject','Unit / System','Question / IMP','Answer Key Points','Source','Last Revised','Last Result','Attempts','Passes','Fails','Streak','Stage','Next Due','Status','Notes','Priority','Fail Rate','Days Left','Data Quality','Actions'].map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${shown.map(c=>`<tr><td><b>#${c.id}</b></td><td>${esc(c.entryDate||'—')}</td><td>${esc(c.subject)}</td><td>${esc(c.unit)}</td><td class="wrap">${esc(c.question)}</td><td class="wrap">${esc(c.answer||'—')}</td><td class="wrap">${esc(c.source||'—')}</td><td>${esc(c.lastRevised||'—')}</td><td>${pillResult(c.lastResult)}</td><td>${c.totalAttempts}</td><td>${c.passes}</td><td>${c.fails}</td><td>${c.streak}</td><td>${c.stage}</td><td>${esc(c.nextDue||'—')}</td><td>${statusPill(c)}</td><td class="wrap">${esc(c.notes||'—')}</td><td>${esc(c.priorityNormLabel||c.priority||'—')}</td><td>${c.totalAttempts?Math.round(c.failRate*100)+'%':'—'}</td><td>${c.daysLeft===''?'—':c.daysLeft}</td><td>${c.dataQuality?`<span class="pill issue">${esc(c.dataQuality)}</span>`:'—'}</td><td><div class="actions">${button('Edit','edit-card','btn small',`data-id="${c.id}"`)}${button('Delete','delete-card','btn small danger',`data-id="${c.id}"`)}</div></td></tr>`).join('')||'<tr><td colspan="22" class="empty">No matching records.</td></tr>'}</tbody></table></div><div class="pagination"><span class="muted tiny">Page ${page+1} of ${Math.max(1,Math.ceil(all.length/pageSize))} · ${pageSize} rows/page</span><div class="actions">${button('← Previous','cards-prev','btn small',page===0?'disabled':'')}${button('Next →','cards-next','btn small',start+pageSize>=all.length?'disabled':'')}</div></div></div>`}
function renderRevisionTable(){let a=computed.revisions.slice();if(revSearch){const q=revSearch.toLowerCase();a=a.filter(r=>[r.logDate,r.impId,r.result,r.notes,r.subjectAuto,r.questionAuto].some(x=>String(x??'').toLowerCase().includes(q)))}a.sort((x,y)=>(y._i-x._i));const shown=a.slice(revPage*50,revPage*50+50);return `${pageTitle('Revision Log','Full review history with add, edit and delete controls. Invalid rows are flagged and excluded from scheduling.',button('＋ Log review','add-revision','btn primary')+button('Export CSV','export-revisions','btn'))}<div class="panel"><div class="toolbar"><input class="field" data-filter="rev-search" value="${esc(revSearch)}" placeholder="Search date, IMP ID, result, notes…"><span class="pill">${a.length} rows</span></div><div class="tablewrap"><table><thead><tr><th>Date</th><th>IMP ID</th><th>Result</th><th>Subject</th><th>Unit</th><th>Question</th><th>Review #</th><th>Data quality</th><th>Actions</th></tr></thead><tbody>${shown.map(r=>`<tr><td>${esc(r.logDate||'—')}</td><td>#${esc(r.impId)}</td><td>${pillResult(r.resultNorm||r.result)}</td><td>${esc(r.subjectAuto||'—')}</td><td>${esc(r.unitAuto||'—')}</td><td class="wrap">${esc(r.questionAuto||'—')}</td><td>${r.reviewNo||'—'}</td><td>${r.dataQuality?`<span class="pill issue">${esc(r.dataQuality)}</span>`:'—'}</td><td><div class="actions">${button('Edit','edit-revision','btn small',`data-index="${r._i}"`)}${button('Delete','delete-revision','btn small danger',`data-index="${r._i}"`)}</div></td></tr>`).join('')||'<tr><td colspan="9" class="empty">No revision rows yet.</td></tr>'}</tbody></table></div><div class="pagination"><span class="muted tiny">Page ${revPage+1} of ${Math.max(1,Math.ceil(a.length/50))}</span><div class="actions">${button('← Previous','rev-prev','btn small',revPage===0?'disabled':'')}${button('Next →','rev-next','btn small',(revPage+1)*50>=a.length?'disabled':'')}</div></div></div>`}
function renderWeak(){const a=computed.failRows;return `${pageTitle('Weak Topics — Top 20 Fails','Cards with recorded failures, ordered by fail count then fail rate.',button('Export CSV','export-weak','btn'))}<div class="panel"><div class="tablewrap"><table><thead><tr><th>Rank</th><th>ID</th><th>Question</th><th>Subject / Unit</th><th>Fails</th><th>Attempts</th><th>Fail rate</th><th>Trend</th><th>Next Due</th><th>Actions</th></tr></thead><tbody>${a.map((c,i)=>`<tr><td>${i+1}</td><td>#${c.id}</td><td class="wrap">${esc(c.question)}</td><td>${esc(c.subject)}<div class="muted tiny">${esc(c.unit)}</div></td><td><b>${c.fails}</b></td><td>${c.totalAttempts}</td><td>${Math.round(c.failRate*100)}%</td><td>${esc(c.trend||'—')}</td><td>${esc(c.nextDue||'—')}</td><td><div class="actions">${button('Study','study-card','btn small',`data-id="${c.id}"`)}${button('Edit','edit-card','btn small',`data-id="${c.id}"`)}</div></td></tr>`).join('')||'<tr><td colspan="10" class="empty">No failures recorded yet.</td></tr>'}</tbody></table></div></div>`}
function unitProgressRows(){const map=new Map();for(const c of computed.cards){const k=c.subject+'\u0000'+c.unit;if(!map.has(k))map.set(k,{subject:c.subject,unit:c.unit,total:0,dueToday:0,mastered:0,inProgress:0,new:0,fails:0});const x=map.get(k);x.total++;if(c.due&&!c.dataQuality)x.dueToday++;if(c.stage>=4)x.mastered++;if(c.stage>=2&&c.stage<=3)x.inProgress++;if(c.new)x.new++;x.fails+=c.fails}const rows=[...map.values()].sort((a,b)=>E.SUBJECTS.indexOf(a.subject)-E.SUBJECTS.indexOf(b.subject)||a.unit.localeCompare(b.unit));rows.forEach(r=>r.progress=r.total?Math.round(r.mastered/r.total*100):0);return rows}
function renderUnitProgress(){const rows=unitProgressRows();return `${pageTitle('Unit Progress','Progress grouped by Subject + Unit, matching the workbook’s Unit Progress layout.',button('Export CSV','export-unit-progress','btn'))}<div class="panel"><div class="statusrow" style="margin-bottom:10px"><span class="pill">${rows.length} subject/unit groups</span><span class="muted tiny">Groups appear once at least one IMP has been entered for that unit.</span></div><div class="tablewrap"><table><thead><tr><th>Subject</th><th>Unit</th><th>Total IMPs</th><th>Due Today</th><th>Mastered</th><th>In Progress</th><th>New</th><th>Progress</th><th>Fails</th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${esc(r.subject)}</b></td><td>${esc(r.unit)}</td><td>${r.total}</td><td>${r.dueToday}</td><td>${r.mastered}</td><td>${r.inProgress}</td><td>${r.new}</td><td><div class="statusrow"><div class="progressline" style="width:100px"><span style="width:${r.progress}%"></span></div>${r.progress}%</div></td><td>${r.fails}</td></tr>`).join('')||'<tr><td colspan="9" class="empty">No units have IMPs yet.</td></tr>'}</tbody></table></div></div>`}
function renderSubjects(){const s=computed.cards.filter(c=>c.subject===subjectSheet);return `${pageTitle('Subject Sheets','Workbook-style subject-specific lists. Choose a subject to view its complete card set.',button('＋ Add IMP','add-card','btn primary'))}<div class="subjectgrid" style="margin-bottom:12px">${E.SUBJECTS.map(sub=>`<button class="subjectcard" data-subject-sheet="${esc(sub)}" style="${subjectSheet===sub?'border-color:#087e8b;background:#eafafa':''}"><strong>${esc(sub)}</strong><div class="substats">${computed.cards.filter(c=>c.subject===sub).length} IMPs · ${computed.cards.filter(c=>c.subject===sub&&c.due).length} due</div></button>`).join('')}</div><div class="panel"><div class="toolbar"><h2 style="margin:0">${esc(subjectSheet)}</h2><span class="pill">${s.length} IMPs</span><button class="btn" data-action="export-subject">Export this subject</button></div>${cardTable(s)}</div>`}
function renderUnits(){return `${pageTitle('Unit Management','Manage the same 12 subjects and their configurable unit lists. Existing historical records are preserved when a unit is removed.',button('Export JSON backup','export-json','btn'))}<div class="notice warn">Before removing or renaming a unit, migrate any cards using the old name. The app will flag mismatched units rather than silently rewriting your data.</div><div class="settinggrid">${E.SUBJECTS.map(sub=>`<section class="settingcard"><h3>${esc(sub)}</h3><div class="muted tiny" style="margin-bottom:7px">${(state.units[sub]||[]).length} units</div><textarea class="area" data-unit-editor="${esc(sub)}" rows="8" style="font-size:12px">${esc((state.units[sub]||[]).join('\n'))}</textarea><button class="btn" data-action="save-units" data-subject="${esc(sub)}" style="margin-top:8px;width:100%">Save ${esc(sub)} units</button></section>`).join('')}</div>`}
function renderIntervals(){return `${pageTitle('Settings — Intervals','Editable review intervals, matching the workbook’s three priority categories.',button('Restore workbook defaults','reset-intervals','btn'))}<div class="settinggrid">${['Regular','Must-Do','Late'].map(p=>`<section class="settingcard"><h3>${esc(p)}</h3><div class="formgrid"><label class="formfield">Fail interval (days)<input class="field" type="number" min="1" max="365" data-interval="${p}" data-field="fail" value="${state.intervals[p].fail}"></label><label class="formfield">Partial interval (days)<input class="field" type="number" min="1" max="365" data-interval="${p}" data-field="partial" value="${state.intervals[p].partial}"></label>${state.intervals[p].pass.map((n,i)=>`<label class="formfield">Stage ${i+1} PASS<input class="field" type="number" min="1" max="730" data-interval="${p}" data-field="pass" data-index="${i}" value="${n}"></label>`).join('')}</div></section>`).join('')}</div><div class="notice">Changes apply immediately to computed due dates. Use positive whole-day intervals. A PASS on exam date minus one may mark the card Done under the workbook exam-cap rule.</div>`}
function renderAnalytics(){const d=computed.dashboard;const totalAttempts=computed.cards.reduce((n,c)=>n+c.totalAttempts,0);return `${pageTitle('Analytics','Review volume, retention, weak areas and study backlog.',button('Export analytics CSV','export-analytics','btn'))}<div class="grid metrics">${metric('Pass rate',`${Math.round(d.overallPassRate*100)}%`,'PASS / all recognized results')}${metric('Total attempts',totalAttempts,'Across all cards')}${metric('Total fails',computed.cards.reduce((n,c)=>n+c.fails,0),'Logged FAIL outcomes')}${metric('Data-quality flags',d.dataIssues+d.revisionIssues,'Fix before trusting due counts')}</div><div class="grid split" style="margin-top:12px"><section class="panel"><h2>Subject performance</h2>${computed.subjects.map(s=>`<div style="margin:12px 0"><div class="statusrow" style="justify-content:space-between"><b>${esc(s.subject)}</b><span class="muted tiny">${s.total} cards · ${s.fails} fails</span></div><div class="progressline" style="margin-top:5px"><span style="width:${s.progress}%"></span></div></div>`).join('')}</section><section class="panel"><h2>Retention overview</h2>${[['Stage 0 · New',computed.cards.filter(c=>c.stage===0).length],['Stage 1',computed.cards.filter(c=>c.stage===1).length],['Stage 2–3',computed.cards.filter(c=>c.stage>=2&&c.stage<=3).length],['Stage 4–5 · Mastered',computed.cards.filter(c=>c.stage>=4).length]].map(([l,n])=>`<div class="barline"><span>${l}</span><div class="bar"><i style="width:${computed.cards.length?Number(n)/computed.cards.length*100:0}%"></i></div><b>${n}</b></div>`).join('')}<div class="notice">Fail rate is based on recorded review outcomes. These analytics describe your app data; they do not predict exam performance.</div></section></div>`}
function renderSettings(){return `${pageTitle('Settings, backups & diagnostics','Control your exam date, protect your data, import/export records and run local checks.')}<div class="grid split"><section class="panel"><h2>Exam date</h2><label class="formfield">Exam date (optional)<input class="field" id="examDate" type="date" value="${esc(state.examDate||'')}"></label><p class="footnote">When set, next due dates are capped at exam date − 1. A PASS on or after that cutoff can mark a card Done according to the workbook rule.</p><div class="actions">${button('Save exam date','save-exam','btn primary')}${button('Clear date','clear-exam','btn')}</div><hr style="border:0;border-top:1px solid var(--line);margin:16px 0"><h2>Data protection</h2><div class="toolbar">${button('Export full JSON backup','export-json','btn primary')}${button('Import JSON / CSV / .xlsx','import-file','btn')}${button('Export cards CSV','export-cards','btn')}${button('Export revisions CSV','export-revisions','btn')}</div><div class="notice good">Auto-save uses IndexedDB on this device, with browser storage fallback. Backups are still essential: clearing site data or uninstalling the app may erase local records.</div></section><section class="panel"><h2>Storage & limits</h2><div class="barline"><span>IMP slots</span><div class="bar"><i style="width:${Math.min(100,state.master.length/1000*100)}%"></i></div><b>${state.master.length}/1000</b></div><div class="barline"><span>Review slots</span><div class="bar"><i style="width:${Math.min(100,state.revisions.length/9999*100)}%"></i></div><b>${state.revisions.length}/9999</b></div><p class="footnote">The original workbook allocates 1,000 IMPs and 9,999 revision rows. This app can hold more, but these workbook-aligned capacity indicators warn before the source workbook limits are reached.</p><h2 style="margin-top:16px">Diagnostics</h2><div class="toolbar">${button('Run engine checks','run-tests','btn primary')}${button('Run 180-day simulation','run-simulation','btn')}</div><div id="testResults">${tests.length?renderTestResults():`<div class="muted smalltext">No diagnostics run in this session yet.</div>`}</div></section></div><section class="panel"><h2>Danger zone</h2><p class="footnote">Resetting clears all local records and restores the workbook seed. Export a backup first. This cannot be undone unless you have a backup.</p>${button('Reset app to workbook seed','reset-app','btn danger')}</section>`}
function renderTestResults(){return `<div class="notice ${tests.every(t=>t.pass)?'good':'warn'}">${tests.filter(t=>t.pass).length}/${tests.length} checks passed in the latest run.</div><div class="tablewrap"><table><thead><tr><th>Check</th><th>Result</th><th>Detail</th></tr></thead><tbody>${tests.map(t=>`<tr><td>${esc(t.name)}</td><td><span class="pill ${t.pass?'pass':'issue'}">${t.pass?'PASS':'FAIL'}</span></td><td class="wrap">${esc(t.detail||'')}</td></tr>`).join('')}</tbody></table></div>`}
function renderModal(){const root=$('#modalroot');if(!modal){root.innerHTML='';return}let title='',body='';if(modal.type==='card'){const c=modal.card||{id:nextId(),entryDate:E.today(),subject:'Medicine',unit:(state.units.Medicine||[])[0]||'',question:'',answer:'',source:'',notes:'',priority:'Regular'};title=modal.edit?'Edit IMP #'+c.id:'Add a new IMP';body=`<form id="cardForm" class="formgrid"><label class="formfield">IMP ID<input class="field" name="id" type="number" min="1" step="1" required value="${esc(c.id)}" ${modal.edit?'readonly':''}></label><label class="formfield">Entry date<input class="field" name="entryDate" type="date" required value="${esc(c.entryDate||E.today())}"></label><label class="formfield">Subject<select class="select" name="subject" required>${E.SUBJECTS.map(s=>`<option ${c.subject===s?'selected':''}>${esc(s)}</option>`).join('')}</select></label><label class="formfield">Unit<select class="select" name="unit" required>${(state.units[c.subject]||[]).map(u=>`<option ${c.unit===u?'selected':''}>${esc(u)}</option>`).join('')}${c.unit&&!(state.units[c.subject]||[]).includes(c.unit)?`<option selected>${esc(c.unit)}</option>`:''}</select><span class="muted tiny">Manage units in Workbook → Unit Management.</span></label><label class="formfield full">Question / IMP<textarea class="area" name="question" required>${esc(c.question||'')}</textarea></label><label class="formfield full">Answer key points<textarea class="area" name="answer">${esc(c.answer||'')}</textarea></label><label class="formfield">Source<input class="field" name="source" value="${esc(c.source||'')}"></label><label class="formfield">Priority<select class="select" name="priority">${['Regular','Must-Do','Late'].map(p=>`<option ${E.normPriority(c.priority)===p?'selected':''}>${p}</option>`).join('')}</select></label><label class="formfield full">Notes<textarea class="area" name="notes">${esc(c.notes||'')}</textarea></label></form><div id="formErrors"></div>`}else if(modal.type==='revision'){const r=modal.revision||{logDate:E.today(),impId:state.master[0]?.id||1,result:'PASS',notes:''};title=modal.edit?'Edit revision':'Log a revision';body=`<form id="revisionForm" class="formgrid"><label class="formfield">Revision date<input class="field" name="logDate" type="date" required value="${esc(r.logDate||E.today())}"></label><label class="formfield">IMP ID<select class="select" name="impId" required>${state.master.map(c=>`<option value="${c.id}" ${Number(r.impId)===Number(c.id)?'selected':''}>#${c.id} · ${esc(c.question.slice(0,55))}</option>`).join('')}</select></label><label class="formfield">Result<select class="select" name="result">${['PASS','FAIL','PARTIAL'].map(x=>`<option ${E.normResult(r.result)===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="formfield full">Notes<textarea class="area" name="notes">${esc(r.notes||'')}</textarea></label></form><div id="formErrors"></div>`}root.innerHTML=`<div class="modal-backdrop" data-action="close-modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modalhead"><h2>${esc(title)}</h2><button class="btn small" data-action="close-modal">✕</button></div><div class="modalbody">${body}</div><div class="modalfoot">${button('Cancel','close-modal','btn')}${button(modal.edit?'Save changes':'Save','save-modal','btn primary')}</div></section></div>`}
function nextId(){return Math.max(0,...state.master.map(c=>Number(c.id)||0))+1}
function openCard(id){const c=id==null?null:state.master.find(x=>Number(x.id)===Number(id));modal={type:'card',edit:!!c,card:c?clone(c):null};renderModal()}
function openRevision(index){const r=index==null?null:state.revisions[index];modal={type:'revision',edit:index!=null,index,revision:r?clone(r):null};renderModal()}
function closeModal(){modal=null;$('#modalroot').innerHTML=''}
function buildQueue(dueOnly=false,oneId=null){let a=computed.cards.filter(c=>!c.dataQuality);if(oneId!=null)a=a.filter(c=>c.id===Number(oneId));else {if(dueOnly)a=a.filter(c=>c.nextDue&&c.nextDue<=E.today());else {a=a.filter(c=>(c.nextDue&&c.nextDue<=E.today())||(study.includeNew&&c.new));if(!a.length)a=computed.cards.filter(c=>!c.dataQuality&&c.nextDue).sort((x,y)=>x.nextDue.localeCompare(y.nextDue)).slice(0,20)}if(study.weak)a.sort((x,y)=>y.failRate-x.failRate||String(x.nextDue).localeCompare(String(y.nextDue)));else a.sort((x,y)=>String(x.nextDue||'9999').localeCompare(String(y.nextDue||'9999')));if(study.shuffle)for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}}study.queue=a.map(c=>c.id);study.idx=0;study.revealed=false;mainTab='study';render()}
function grade(result){const id=study.queue[study.idx],c=computed.cards.find(x=>x.id===id);if(!c)return;undoSnapshot={state:clone(state),study:clone(study),message:`Undo grade for #${id}`};const next=clone(state);next.revisions.push({logDate:E.today(),impId:id,result,notes:''});state=normalizeState(next);recalc();study.idx=study.idx+1;study.revealed=false;render();save();toast(`#${id} graded ${result}`,'ok','undo')}
function undo(){if(!undoSnapshot){toast('Nothing to undo.','error');return}state=normalizeState(undoSnapshot.state);if(undoSnapshot.study)study=clone(undoSnapshot.study);undoSnapshot=null;recalc();render();save();toast('Last change undone.')}
function destructiveSnapshot(){undoSnapshot={state:clone(state),study:clone(study),message:'Undo deletion'}}
function deleteCard(id){const c=state.master.find(x=>Number(x.id)===Number(id));if(!c)return;const n=state.revisions.filter(r=>Number(r.impId)===Number(id)).length;if(!confirm(`Delete IMP #${id} and its ${n} associated revision record(s)? This will affect SRS calculations. Export a backup first if unsure.`))return;destructiveSnapshot();const next=clone(state);next.master=next.master.filter(x=>Number(x.id)!==Number(id));next.revisions=next.revisions.filter(r=>Number(r.impId)!==Number(id));commit(next,`Deleted IMP #${id} and ${n} reviews.`);toast('Deletion can be reversed until the next destructive action.','ok','undo')}
function deleteSelectedCards(){const ids=new Set([...selectedIds].map(Number));const targets=state.master.filter(c=>ids.has(Number(c.id)));if(!targets.length){selectedIds.clear();render();return}const revCount=state.revisions.filter(r=>ids.has(Number(r.impId))).length;if(!confirm(`Delete ${targets.length} selected IMPs and ${revCount} linked revision rows? This changes scheduling and cannot be recovered except with Undo or a backup.`))return;destructiveSnapshot();const next=clone(state);next.master=next.master.filter(c=>!ids.has(Number(c.id)));next.revisions=next.revisions.filter(r=>!ids.has(Number(r.impId)));selectedIds.clear();page=0;commit(next,`Deleted ${targets.length} IMPs and ${revCount} linked reviews.`);toast('Bulk deletion can be reversed with Undo.','ok','undo')}
function deleteRevision(index){const r=state.revisions[index];if(!r)return;if(!confirm(`Delete revision for IMP #${r.impId} dated ${r.logDate||'unknown'} (${r.result||'no result'})?`))return;destructiveSnapshot();const next=clone(state);next.revisions.splice(index,1);commit(next,'Revision deleted.');toast('Revision deletion can be undone.','ok','undo')}
function download(name,content,type){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500)}
function exportJSON(){download(`mbbs-recall-backup-${E.today()}.json`,JSON.stringify(state,null,2),'application/json');toast('Full JSON backup exported.')}
function exportCards(list=state.master){const byId=new Map(computed.cards.map(c=>[Number(c.id),c]));const rows=list.map(c=>{const d=byId.get(Number(c.id))||{};return {ID:c.id,EntryDate:c.entryDate,Subject:c.subject,Unit:c.unit,Question:c.question,Answer:c.answer||'',Source:c.source||'',LastRevised:d.lastRevised||'',LastResult:d.lastResult||'',TotalAttempts:d.totalAttempts||0,Passes:d.passes||0,Fails:d.fails||0,Streak:d.streak||0,Stage:d.stage||0,NextDue:d.nextDue||'',Status:d.status||'',Notes:c.notes||'',Priority:c.priority,FailRate:d.failRate||0,DaysLeft:d.daysLeft??'',DataQuality:d.dataQuality||''}});const headers=['ID','EntryDate','Subject','Unit','Question','Answer','Source','LastRevised','LastResult','TotalAttempts','Passes','Fails','Streak','Stage','NextDue','Status','Notes','Priority','FailRate','DaysLeft','DataQuality'];download(`mbbs-cards-${E.today()}.csv`,E.toCSV(rows,headers),'text/csv;charset=utf-8');toast('Full Master Entry CSV exported, including computed helper fields.')}
function exportRevisions(){const rows=state.revisions.map(r=>({LogDate:r.logDate,IMP_ID:r.impId,Result:r.result,Notes:r.notes||''}));download(`mbbs-revisions-${E.today()}.csv`,E.toCSV(rows,['LogDate','IMP_ID','Result','Notes']),'text/csv;charset=utf-8');toast('Revision CSV exported.')}
function exportRows(name,rows){if(!rows.length){toast('No rows to export.','error');return}download(`${name}-${E.today()}.csv`,E.toCSV(rows,Object.keys(rows[0])),'text/csv;charset=utf-8');toast('CSV exported.')}
function importFile(){const f=$('#fileInput');f.value='';f.click()}
function parseImportCSV(text){const rows=E.parseCSV(text);if(!rows.length)throw Error('CSV is empty.');const norm=x=>String(x||'').trim().toLowerCase().replace(/[^a-z0-9]/g,'');let headerIndex=rows.findIndex(r=>{const h=r.map(norm);return h.some(x=>x==='id'||x.startsWith('impid'))&&h.some(x=>x.startsWith('subject')||x.startsWith('result'))&&h.some(x=>x.startsWith('question')||x.startsWith('result'))});if(headerIndex<0)throw Error('Could not find a recognizable Master Entry or Revision Log header row. Export the workbook sheet as CSV and try again.');const headers=rows[headerIndex].map(norm),data=rows.slice(headerIndex+1),idx=(...names)=>{for(const n of names){const target=norm(n);let i=headers.indexOf(target);if(i<0)i=headers.findIndex(h=>h.startsWith(target)||target.startsWith(h));if(i>=0)return i}return -1};if(idx('LogDate','Log Date')>=0&&idx('Result')>=0&&idx('IMP_ID','IMP ID')>=0){const parsed=data.map(r=>({logDate:csvDate(r[idx('LogDate','Log Date')]),impId:Number(r[idx('IMP_ID','IMP ID')]),result:r[idx('Result')]||'',notes:r[idx('Notes')]||''})).filter(r=>r.logDate||r.impId||r.result);return {type:'revisions',rows:parsed}}if(idx('Question','Question / IMP','Question - DO TODAY')>=0&&idx('Subject')>=0){const parsed=data.map(r=>({id:Number(r[idx('ID','IMP ID')]),entryDate:csvDate(r[idx('EntryDate','Entry Date','Entry Date Ctrl static')]),subject:r[idx('Subject')]||'',unit:r[idx('Unit','Unit / System')]||'',question:r[idx('Question','Question / IMP','Question - DO TODAY')]||'',answer:r[idx('Answer','Answer Key Points')]||'',source:r[idx('Source')]||'',notes:r[idx('Notes','Notes YOU ENTER')]||'',priority:r[idx('Priority','Priority Regular Must-Do Late')]||'Regular'})).filter(r=>r.id||r.question);return {type:'cards',rows:parsed}}throw Error('CSV headers are not recognized. Use a Master Entry or Revision Log CSV.')}
function csvDate(v){if(!v)return '';let s=String(v).trim();if(/^\d{4}-\d\d-\d\d$/.test(s))return E.validDate(s)?s:'';const m=s.match(/^(\d{1,2})[-/ ]([A-Za-z]{3,}|\d{1,2})[-/ ](\d{4})$/);if(m){const months={jan:1,feb:2,mar:3,apr:4,may:5,jun:6,jul:7,aug:8,sep:9,oct:10,nov:11,dec:12};let day=Number(m[1]),mo=/^\d+$/.test(m[2])?Number(m[2]):months[m[2].slice(0,3).toLowerCase()];if(!/^\d+$/.test(m[2])){}else if(day<=12&&mo>12){const temp=day;day=mo;mo=temp}const out=`${m[3]}-${String(mo).padStart(2,'0')}-${String(day).padStart(2,'0')}`;return E.validDate(out)?out:''}return ''}
function runTests(){const out=[],test=(name,fn)=>{try{const x=fn();out.push({name,pass:!!x.pass,detail:x.detail||''})}catch(e){out.push({name,pass:false,detail:String(e)})}};const base=()=>({master:[{id:1,entryDate:'2026-01-01',subject:'Medicine',unit:'Cardiology',question:'Q',priority:'Regular'}],revisions:[],examDate:'',intervals:clone(E.DEFAULT_INTERVALS),units:{Medicine:['Cardiology']}});
 test('Strict calendar date validation',()=>({pass:!E.validDate('2026-02-31')&&E.validDate('2024-02-29'),detail:'Invalid leap date rejected; real leap day accepted'}));
 test('New-card jitter matches ID MOD 5',()=>({pass:E.compute(base(),'2026-01-01').cards[0].rawDue==='2026-01-03',detail:'ID 1 → entry date + 1 + MOD(1,5) = +2 days'}));
 test('FAIL resets streak and uses fail interval',()=>{let s=base();s.revisions=[{logDate:'2026-01-02',impId:1,result:'PASS'},{logDate:'2026-01-03',impId:1,result:'FAIL'}];let c=E.compute(s,'2026-01-03').cards[0];return {pass:c.streak===0&&c.rawDue==='2026-01-04',detail:`streak=${c.streak}, rawDue=${c.rawDue}`}});
 test('PARTIAL preserves previous PASS-day streak',()=>{let s=base();s.revisions=[{logDate:'2026-01-02',impId:1,result:'PASS'},{logDate:'2026-01-03',impId:1,result:'PARTIAL'}];let c=E.compute(s,'2026-01-03').cards[0];return {pass:c.streak===1&&c.rawDue==='2026-01-05',detail:`streak=${c.streak}, rawDue=${c.rawDue}`}});
 test('Same-day PASS attempts count once for streak',()=>{let s=base();s.revisions=[{logDate:'2026-01-02',impId:1,result:'PASS'},{logDate:'2026-01-02',impId:1,result:'PASS'}];let c=E.compute(s,'2026-01-02').cards[0];return {pass:c.streak===1,detail:`streak=${c.streak}`}});
 test('Exam cap blocks beyond exam minus one',()=>{let s=base();s.examDate='2026-01-10';let c=E.compute(s,'2026-01-01').cards[0];return {pass:c.nextDue<='2026-01-09',detail:`nextDue=${c.nextDue}`}});
 test('PASS on exam minus one marks Done',()=>{let s=base();s.examDate='2026-01-10';s.revisions=[{logDate:'2026-01-09',impId:1,result:'PASS'}];let c=E.compute(s,'2026-01-09').cards[0];return {pass:c.nextDue==='',detail:`nextDue=${c.nextDue||'empty'}`}});
 test('Duplicate IDs are blocked from scheduling',()=>{let s=base();s.master.push({...s.master[0],question:'duplicate'});let cs=E.compute(s,'2026-01-01').cards;return {pass:cs.every(c=>c.dataQuality.includes('Duplicate ID')&&!c.nextDue),detail:cs.map(c=>c.dataQuality).join(' | ')}});
 test('Unknown revision ID is flagged and ignored',()=>{let s=base();s.revisions=[{logDate:'2026-01-02',impId:999,result:'PASS'}];let x=E.compute(s,'2026-01-02');return {pass:x.revisions[0].dataQuality.includes('Unknown IMP ID')&&x.cards[0].totalAttempts===0,detail:x.revisions[0].dataQuality}});
 test('Unit mismatch blocks due calculation',()=>{let s=base();s.master[0].unit='Not configured';let c=E.compute(s,'2026-01-01').cards[0];return {pass:c.dataQuality.includes("Unit doesn't match")&&!c.nextDue,detail:c.dataQuality}});
 test('Invalid result does not change schedule',()=>{let s=base();s.revisions=[{logDate:'2026-01-02',impId:1,result:'garbage'}];let c=E.compute(s,'2026-01-02').cards[0];return {pass:c.totalAttempts===0&&c.new,detail:`attempts=${c.totalAttempts}, new=${c.new}`}});
 test('All 12 workbook subjects and units are loaded',()=>({pass:E.SUBJECTS.length===12&&E.SUBJECTS.every(s=>Array.isArray(state.units[s])&&state.units[s].length>0),detail:`${E.SUBJECTS.length} subjects; ${E.SUBJECTS.reduce((n,s)=>n+state.units[s].length,0)} configured units`}));
 tests=out;const el=$('#testResults');if(el)el.innerHTML=renderTestResults();toast(`${out.filter(t=>t.pass).length}/${out.length} engine checks passed.`,out.every(t=>t.pass)?'ok':'error');render()}
function saveCardForm(){const f=$('#cardForm');if(!f)return;const fd=new FormData(f),c={id:Number(fd.get('id')),entryDate:String(fd.get('entryDate')||''),subject:String(fd.get('subject')||''),unit:String(fd.get('unit')||''),question:String(fd.get('question')||''),answer:String(fd.get('answer')||''),source:String(fd.get('source')||''),notes:String(fd.get('notes')||''),priority:String(fd.get('priority')||'Regular')};const errors=E.validateCard(c,state,modal.edit?modal.card.id:null);if(errors.length){$('#formErrors').innerHTML=`<div class="notice error">${errors.map(esc).join('<br>')}</div>`;return}const next=clone(state);if(modal.edit){const idx=next.master.findIndex(x=>Number(x.id)===Number(modal.card.id));if(idx<0)return;next.master[idx]=c}else next.master.push(c);const wasEdit=modal.edit;closeModal();page=0;commit(next,wasEdit?'IMP updated.':'IMP added.');}
function saveRevisionForm(){const f=$('#revisionForm');if(!f)return;const fd=new FormData(f),r={logDate:String(fd.get('logDate')||''),impId:Number(fd.get('impId')),result:String(fd.get('result')||''),notes:String(fd.get('notes')||'')};const errors=E.validateRevision(r,state);if(errors.length){$('#formErrors').innerHTML=`<div class="notice error">${errors.map(esc).join('<br>')}</div>`;return}const next=clone(state);if(modal.edit)next.revisions[modal.index]=r;else next.revisions.push(r);const wasEdit=modal.edit;closeModal();commit(next,wasEdit?'Revision updated.':'Revision logged.')}
function handleAction(a,el){const id=Number(el.dataset.id),idx=Number(el.dataset.index);switch(a){case'add-card':openCard();break;case'edit-card':openCard(id);break;case'delete-card':deleteCard(id);break;case'add-revision':openRevision();break;case'edit-revision':openRevision(idx);break;case'delete-revision':deleteRevision(idx);break;case'close-modal':closeModal();break;case'close-modal-backdrop':if(el.classList.contains('modal-backdrop'))closeModal();break;case'save-modal':if(modal?.type==='card')saveCardForm();else if(modal?.type==='revision')saveRevisionForm();break;case'export-json':exportJSON();break;case'export-cards':exportCards();break;case'export-revisions':exportRevisions();break;case'import-file':importFile();break;case'start-study':buildQueue();break;case'rebuild-queue':buildQueue();break;case'study-due':buildQueue(true);break;case'study-card':buildQueue(false,id);break;case'reveal':study.revealed=true;render();break;case'grade':grade(el.dataset.result);break;case'study-prev':study.idx=Math.max(0,study.idx-1);study.revealed=false;render();break;case'study-next':study.idx=Math.min(study.queue.length,study.idx+1);study.revealed=false;render();break;case'undo':undo();break;case'select-matching':filteredCards().forEach(c=>selectedIds.add(Number(c.id)));render();toast(`${selectedIds.size} IMPs selected.`);break;case'clear-selection':selectedIds.clear();render();break;case'delete-selected':deleteSelectedCards();break;case'clear-filters':search='';subjectFilter='All';statusFilter='All';sortCards='id-asc';selectedIds.clear();page=0;render();break;case'cards-prev':page=Math.max(0,page-1);render();break;case'cards-next':page++;render();break;case'rev-prev':revPage=Math.max(0,revPage-1);render();break;case'rev-next':revPage++;render();break;case'wb-today':mainTab='workbook';wbTab='today';render();break;case'wb-master':mainTab='workbook';wbTab='master';render();break;case'save-exam':{const val=$('#examDate').value;if(val&&!E.validDate(val)){toast('Enter a valid exam date.','error');break}const n=clone(state);n.examDate=val;commit(n,'Exam date saved.');break}case'clear-exam':{const n=clone(state);n.examDate='';commit(n,'Exam date cleared.');break}case'run-tests':runTests();break;case'run-simulation':runSimulationUI();break;case'reset-intervals':{if(!confirm('Restore all review intervals to workbook defaults?'))break;const n=clone(state);n.intervals=clone(E.DEFAULT_INTERVALS);commit(n,'Workbook interval defaults restored.');break}case'save-units':{const sub=el.dataset.subject,field=document.querySelector(`[data-unit-editor="${CSS.escape(sub)}"]`);const units=field.value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean);if(units.length>200){toast('A subject can have at most 200 configured units.','error');break}if(new Set(units.map(x=>x.toLowerCase())).size!==units.length){toast('Duplicate unit names are not allowed.','error');break}const n=clone(state);n.units[sub]=units;commit(n,`${sub} unit list saved.`);break}case'reset-app':if(confirm('Reset all local app data to the original workbook seed? Export a backup first.')){state=normalizeState(fresh());undoSnapshot=null;recalc();render();save();toast('App reset to workbook seed.')}break;case'export-subject':exportCards(state.master.filter(c=>c.subject===subjectSheet));break;case'export-weak':exportRows('mbbs-weak-topics',computed.failRows.map(c=>({ID:c.id,Subject:c.subject,Unit:c.unit,Question:c.question,Fails:c.fails,Attempts:c.totalAttempts,FailRate:c.failRate,Trend:c.trend,NextDue:c.nextDue,Priority:c.priority})));break;case'export-unit-progress':exportRows('mbbs-unit-progress',unitProgressRows());break;case'export-analytics':exportRows('mbbs-analytics',computed.subjects.map(s=>({...s,passRate:computed.dashboard.overallPassRate})));break;}}
function runSimulationUI(){const root=$('#testResults');if(root)root.innerHTML='<div class="notice">Running 180-day simulation through the actual schedule engine…</div>';toast('180-day simulation started.');setTimeout(()=>{const results=[];for(const [total,capacity] of [[300,30],[600,50],[1000,60]]){const units=state.units,intervals=state.intervals;const master=Array.from({length:total},(_,i)=>{const subject=E.SUBJECTS[i%E.SUBJECTS.length],list=units[subject]||['General'];return {id:i+1,entryDate:E.addDays('2026-01-01',Math.floor(i*180/total)),subject,unit:list[i%list.length],question:`Simulation card ${i+1}`,priority:i%3===0?'Must-Do':i%5===0?'Late':'Regular'}});let revisions=[],daily=[],maxBacklog=0;for(let d=0;d<180;d++){const today=E.addDays('2026-01-01',d),calc=E.compute({master,revisions,examDate:'',intervals,units},today);const due=calc.cards.filter(c=>c.nextDue&&c.nextDue<=today&&!c.dataQuality).sort((a,b)=>a.nextDue.localeCompare(b.nextDue)||a.id-b.id);maxBacklog=Math.max(maxBacklog,due.length);const chosen=due.slice(0,capacity);for(const c of chosen){let z=(Math.imul(c.id,73856093)^Math.imul(d+1,19349663)^0x9e3779b9)>>>0;z^=z<<13;z^=z>>>17;z^=z<<5;const x=(z>>>0)%100;const result=x<75?'PASS':x<88?'PARTIAL':'FAIL';revisions.push({logDate:today,impId:c.id,result,notes:''})}daily.push({day:d,due:due.length,reviewed:chosen.length})}const last=daily.slice(-30),avg=Math.round(last.reduce((a,b)=>a+b.due,0)/last.length*10)/10;results.push({name:`180-day simulation · ${total} cards · ${capacity}/day`,pass:daily.length===180&&daily.every(d=>Number.isFinite(d.due)&&d.due>=0&&d.reviewed<=capacity),detail:`${revisions.length} reviews; average due last 30 days ${avg}; max daily backlog ${maxBacklog}; day-180 due ${daily.at(-1).due}. Deterministic engine simulation, not a prediction.`})}tests=results;const r=$('#testResults');if(r)r.innerHTML=renderTestResults();toast('180-day simulation finished. Results are saved in this view.');},30)}
async function importWorkbookXLSX(file){
 if(!window.MBBSXLSXImporter)throw Error('The workbook importer is missing. Re-upload all app files, including xlsx-import.js.');
 const book=await window.MBBSXLSXImporter.parse(file);if(!book.master.length)throw Error('No IMP rows were found in Master Entry. Check that the workbook contains actual records, not only headers.');
 const ids=new Set();for(const c of book.master){if(ids.has(Number(c.id)))throw Error(`Duplicate IMP ID ${c.id} in workbook; fix duplicate IDs before importing.`);ids.add(Number(c.id));}
 const summary=`Workbook detected: ${book.counts.master} IMPs, ${book.counts.revisions} revision rows, ${book.counts.subjects} subjects, ${book.counts.units} configured units.\n\nExport a full JSON backup before continuing. Cards with matching IDs will be replaced; other app cards will remain. Existing reviews will be kept and exact duplicate workbook reviews skipped. Subject unit lists and intervals will be replaced by workbook settings. A nonblank workbook exam date will replace the app exam date.\n\nContinue?`;
 if(!confirm(summary))return;
 const next=clone(state),byId=new Map(next.master.map(c=>[Number(c.id),c]));for(const c of book.master)byId.set(Number(c.id),c);next.master=[...byId.values()];
 const revKey=r=>[String(r.logDate||''),String(Number(r.impId)||''),E.normResult(r.result)||String(r.result||'').trim().toUpperCase(),String(r.notes||'')].join('\u0000');
 const seen=new Set(next.revisions.map(revKey));for(const r of book.revisions){const k=revKey(r);if(!seen.has(k)){next.revisions.push(r);seen.add(k);}}
 next.units=book.units;next.intervals=book.intervals;if(book.examDate)next.examDate=book.examDate;
 state=normalizeState(next);recalc();render();save();toast(`Workbook imported: ${book.master.length} IMPs, ${book.revisions.length} revisions. Existing records were merged.`);
}
async function handleImportFile(f){try{const name=f.name.toLowerCase();if(name.endsWith('.xlsx')){await importWorkbookXLSX(f);return;}const text=await f.text();if(name.endsWith('.json')){const parsed=JSON.parse(text);if(!parsed||!Array.isArray(parsed.master)||!Array.isArray(parsed.revisions))throw Error('JSON does not look like an MBBS Recall backup.');if(!confirm(`Restore backup containing ${parsed.master.length} IMPs and ${parsed.revisions.length} reviews? Current app data will be replaced.`))return;state=normalizeState(parsed);recalc();render();save();toast('JSON backup restored.')}else{const imp=parseImportCSV(text);const next=clone(state);if(imp.type==='cards'){if(!confirm(`Import ${imp.rows.length} cards? Existing cards with the same ID will be replaced; other cards remain.`))return;const map=new Map(next.master.map(c=>[Number(c.id),c]));for(const c of imp.rows){if(Number.isInteger(c.id)&&c.id>0)map.set(c.id,c)}next.master=[...map.values()];}else{if(!confirm(`Import ${imp.rows.length} revision rows? They will be appended; existing reviews are retained.`))return;next.revisions.push(...imp.rows)}state=normalizeState(next);recalc();render();save();toast(`${imp.rows.length} ${imp.type==='cards'?'cards':'reviews'} imported.`)}}catch(err){toast(`Import failed: ${err.message||err}`,'error')}finally{$('#fileInput').value='';}}
// Delegated interactions
$('#toasts').addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b)handleAction(b.dataset.action,b)});$('#topnav').addEventListener('click',e=>{const b=e.target.closest('[data-tab]');if(b)setMain(b.dataset.tab)});$('#mobilebar').addEventListener('click',e=>{const b=e.target.closest('[data-tab]');if(b)setMain(b.dataset.tab)});$('#view').addEventListener('click',e=>{const b=e.target.closest('[data-action],[data-wbtab],[data-subject-sheet]');if(!b)return;if(b.dataset.wbtab){wbTab=b.dataset.wbtab;render();return}if(b.dataset.subjectSheet){subjectSheet=b.dataset.subjectSheet;render();return}if(b.dataset.action)handleAction(b.dataset.action,b)});$('#modalroot').addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;if(b.classList.contains('modal-backdrop')){if(e.target===b)closeModal();return}handleAction(b.dataset.action,b)});$('#modalroot').addEventListener('change',e=>{const el=e.target;if(el.name==='subject'&&modal?.type==='card'){const unit=$('#cardForm [name="unit"]');const units=state.units[el.value]||[];unit.innerHTML=units.map(x=>`<option>${esc(x)}</option>`).join('');}});$('#view').addEventListener('change',e=>{const el=e.target;if(el.dataset.filter==='subject'){subjectFilter=el.value;page=0;render()}if(el.dataset.filter==='status'){statusFilter=el.value;page=0;render()}if(el.dataset.filter==='sort'){sortCards=el.value;page=0;render()}if(el.dataset.selectVisible){const ids=Array.from(document.querySelectorAll('[data-select-id]')).map(x=>Number(x.dataset.selectId));ids.forEach(id=>el.checked?selectedIds.add(id):selectedIds.delete(id));render()}if(el.dataset.selectId){const id=Number(el.dataset.selectId);if(el.checked)selectedIds.add(id);else selectedIds.delete(id);render()}if(el.dataset.setting){study[el.dataset.setting]=el.checked;render()}if(el.dataset.interval){const p=el.dataset.interval,f=el.dataset.field,n=Number(el.value);if(!Number.isInteger(n)||n<1||n>(f==='pass'?730:365)){toast('Intervals must be positive whole numbers within the allowed range.','error');render();return}const next=clone(state);if(f==='pass')next.intervals[p].pass[Number(el.dataset.index)]=n;else next.intervals[p][f]=n;commit(next,'Review interval updated.')}});$('#view').addEventListener('input',e=>{const el=e.target;if(el.dataset.filter==='search'){search=el.value;page=0;const pos=el.selectionStart;render();const n=$('#view [data-filter="search"]');if(n){n.focus();n.setSelectionRange(pos,pos)}}if(el.dataset.filter==='rev-search'){revSearch=el.value;revPage=0;const pos=el.selectionStart;render();const n=$('#view [data-filter="rev-search"]');if(n){n.focus();n.setSelectionRange(pos,pos)}}});$('#fileInput').addEventListener('change',e=>{const f=e.target.files?.[0];if(f)handleImportFile(f)});
document.addEventListener('keydown',e=>{if(modal){if(e.key==='Escape')closeModal();return}if(mainTab==='study'){if(e.code==='Space'){e.preventDefault();study.revealed=!study.revealed;render()}else if(e.key==='1'&&study.revealed)grade('FAIL');else if(e.key==='2'&&study.revealed)grade('PARTIAL');else if(e.key==='3'&&study.revealed)grade('PASS');else if(e.key==='ArrowRight'){study.idx=Math.min(study.queue.length,study.idx+1);study.revealed=false;render()}else if(e.key==='ArrowLeft'){study.idx=Math.max(0,study.idx-1);study.revealed=false;render()}}});
boot();
})();
